  KEY `fk_voucher_sub_ledger_history_sub_center_code` (`sub_center_code`),
  KEY `fk_voucher_sub_ledger_history_sub_ledger_code` (`sub_ledger_code`),
  KEY `fk_voucher_sub_ledger_history_voucher_entry_code` (`voucher_entry_code`),
  CONSTRAINT `fk_voucher_sub_ledger_history_dcs_code` FOREIGN KEY (`dcs_code`) REFERENCES `tbl_dcs` (`dcs_code`),
  CONSTRAINT `fk_voucher_sub_ledger_history_sub_center_code` FOREIGN KEY (`sub_center_code`) REFERENCES `tbl_sub_center` (`sub_center_code`),
  CONSTRAINT `fk_voucher_sub_ledger_history_sub_ledger_code` FOREIGN KEY (`sub_ledger_code`) REFERENCES `tbl_sub_ledger` (`sub_ledger_code`),
  CONSTRAINT `fk_voucher_sub_ledger_history_voucher_entry_code` FOREIGN KEY (`voucher_entry_code`) REFERENCES `tbl_voucher_entry` (`voucher_entry_code`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

