-- -------------------------------------------
-- TABLE `user`
-- -------------------------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE IF NOT EXISTS `user` (
  `id` varchar(14) NOT NULL,
  `auth_key` varchar(50) DEFAULT NULL,
  `bind_to_ip` varchar(255) DEFAULT NULL,
  `confirmation_token` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `email` varchar(128) DEFAULT NULL,
  `email_confirmed` tinyint(4) DEFAULT '0',
  `flg_sentbox_entry` char(1) DEFAULT NULL,
  `is_active` int(11) DEFAULT NULL,
  `is_delete` int(11) DEFAULT NULL,
  `mobile_no` varchar(10) DEFAULT NULL,
  `name` varchar(255) NOT NULL,
  `password_hash` varchar(100) NOT NULL,
  `portal_type` varchar(50) DEFAULT NULL,
  `registration_ip` varchar(15) DEFAULT NULL,
  `status` int(11) DEFAULT '1',
  `superadmin` int(11) DEFAULT '0',
  `sync_status` char(1) DEFAULT NULL,
  `sync_timestamp` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `user_code` varchar(14) DEFAULT NULL,
  `user_identity` varchar(255) DEFAULT NULL,
  `username` varchar(255) DEFAULT NULL,
  `alert_recipient_group_id` int(11) DEFAULT NULL,
  `created_by` varchar(14) DEFAULT NULL,
  `deleted_by` varchar(14) DEFAULT NULL,
  `updated_by` varchar(14) DEFAULT NULL,
  `user_type_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_user_alert_recipient_group_id` (`alert_recipient_group_id`),
  KEY `fk_users_created_by` (`created_by`),
  KEY `fk_users_deleted_by` (`deleted_by`),
  KEY `fk_users_updated_by` (`updated_by`),
  KEY `fk_users_user_type_id` (`user_type_id`),
  CONSTRAINT `fk_user_alert_recipient_group_id` FOREIGN KEY (`alert_recipient_group_id`) REFERENCES `tbl_alert_recipient_group` (`id`),
  CONSTRAINT `fk_users_created_by` FOREIGN KEY (`created_by`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_users_deleted_by` FOREIGN KEY (`deleted_by`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_users_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `user` (`id`),
  CONSTRAINT `fk_users_user_type_id` FOREIGN KEY (`user_type_id`) REFERENCES `tbl_user_types` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

-- -------------------------------------------
-- TABLE `user_history`
-- -------------------------------------------
DROP TABLE IF EXISTS `user_history`;
CREATE TABLE IF NOT EXISTS `user_history` (
  `user_history_id` bigint(20) NOT NULL AUTO_INCREMENT,
  `id` varchar(14) DEFAULT NULL,
  `auth_key` varchar(50) DEFAULT NULL,
  `bind_to_ip` varchar(255) DEFAULT NULL,
  `confirmation_token` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `deleted_at` datetime(6) DEFAULT NULL,
  `email` varchar(128) DEFAULT NULL,
  `email_confirmed` tinyint(4) DEFAULT '0',
  `mobile_no` varchar(10) DEFAULT NULL,
  `alert_recipient_group_id` int(11) DEFAULT NULL,
  `flg_sentbox_entry` char(1) DEFAULT NULL,
  `is_active` int(11) DEFAULT NULL,
  `is_delete` int(11) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `password_hash` varchar(100) DEFAULT NULL,
  `registration_ip` varchar(15) DEFAULT NULL,
  `status` int(11) DEFAULT '1',
  `superadmin` int(11) DEFAULT '0',
  `sync_status` char(1) DEFAULT NULL,
  `sync_timestamp` datetime(6) DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `user_code` varchar(14) DEFAULT NULL,
  `username` varchar(255) DEFAULT NULL,
  `created_by` varchar(14) DEFAULT NULL,
  `deleted_by` varchar(14) DEFAULT NULL,
  `updated_by` varchar(14) DEFAULT NULL,
  `user_type_id` int(11) DEFAULT NULL,
  `portal_type` varchar(15) DEFAULT NULL,
  `user_identity` varchar(255) DEFAULT NULL,
  `history_created_at` datetime DEFAULT NULL,
  `operation_type` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`user_history_id`),
  KEY `fk_users_created_by` (`created_by`),
  KEY `fk_users_deleted_by` (`deleted_by`),
  KEY `fk_users_updated_by` (`updated_by`),
  KEY `fk_users_user_type_id` (`user_type_id`)
) ENGINE=InnoDB  DEFAULT CHARSET=latin1;

-- -------------------------------------------
-- TABLE `user_visit_log`
-- -------------------------------------------
DROP TABLE IF EXISTS `user_visit_log`;
CREATE TABLE IF NOT EXISTS `user_visit_log` (
  `id` int(11) NOT NULL DEFAULT '0',
  `token` varchar(255) NOT NULL,
  `ip` varchar(15) NOT NULL,
  `language` char(2) NOT NULL,
  `user_agent` varchar(255) NOT NULL,
  `user_id` int(11) DEFAULT NULL,
  `visit_time` int(11) NOT NULL,
  `browser` varchar(30) DEFAULT NULL,
  `os` varchar(20) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

