DELIMITER $$
DROP PROCEDURE IF EXISTS `sp_delete_master_geo`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_master_geo`(IN master_table_name VARCHAR(100), IN local_table_name VARCHAR(100), IN local_history_table_name VARCHAR(100), IN master_code VARCHAR(50), IN pk_col_name VARCHAR(50), IN deleted_by VARCHAR(25), OUT resp INT)
BEGIN
	DECLARE len INT DEFAULT 0;
    DECLARE is_exception INT DEFAULT 0;
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN SET is_exception := 1; SET resp := 1; ROLLBACK; END;
	
    START TRANSACTION;
    
    SELECT CHAR_LENGTH(local_history_table_name) INTO len;
	IF len > 0 THEN
		SET @SQL := CONCAT('DELETE FROM ', local_history_table_name, ' WHERE ', pk_col_name, ' = \'', master_code, '\'');
		PREPARE stmt FROM @SQL;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;
	END IF;
	
    SELECT CHAR_LENGTH(local_table_name) INTO len;
    IF len > 0 THEN
		SET @SQL := CONCAT('DELETE FROM ', local_table_name, ' WHERE ', pk_col_name, ' = \'', master_code, '\'');
		PREPARE stmt FROM @SQL;
		EXECUTE stmt;
		DEALLOCATE PREPARE stmt;
    END IF;
    
	SET @SQL := CONCAT('DELETE FROM ', master_table_name, ' WHERE ', pk_col_name, ' = \'', master_code, '\'');
	PREPARE stmt FROM @SQL;
	EXECUTE stmt;
	DEALLOCATE PREPARE stmt;

	IF is_exception = 0 THEN
		ROLLBACK;
		SET resp := 0;
    END IF;
END$$
-- -------------------------------------------
DROP PROCEDURE IF EXISTS `sp_delete_master_global`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_master_global`(IN master_table_name VARCHAR(100), IN local_table_name VARCHAR(100), IN local_history_table_name VARCHAR(100), IN master_code INT, IN pk_col_name VARCHAR(50), IN deleted_by VARCHAR(25), OUT resp INT)
BEGIN
	DECLARE len INT DEFAULT 0;
    DECLARE is_exception INT DEFAULT 0;
    
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN SET is_exception := 1; SET resp := 1; ROLLBACK; END;
	
